sql:
SELECT *
FROM suppliers
WHERE LENGTH(supplier_name) > 14;

SELECT status, customer_id, ROUND(monthly_fee * 0.9, 2) AS monthly_fee_scaled
FROM subscriptions
WHERE YEAR(end_date) >= 2025 AND start_date < '2023-07-01';

SELECT shipments.id, shipments.shipped_date, shipments.status
FROM shipments
WHERE shipments.order_id NOT IN (SELECT id FROM orders WHERE amount < 960);

select departments.id, departments.location, departments.dept_name
from departments
where departments.location in ('Singapore', 'New York', 'Berlin') and not exists (select 1 from employees where employees.dept_id = departments.id);

SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, SUM(sqft) AS total_sqft, ROUND(SUM(sqft) * 100.0 / SUM(SUM(sqft)) OVER (), 2) AS pct_of_total
FROM stores
GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END;

SELECT subscriptions.id, subscriptions.monthly_fee
FROM subscriptions
WHERE subscriptions.customer_id NOT IN (SELECT id FROM customers WHERE email IS NOT NULL);

SELECT a.id, a.status
FROM accounts a
WHERE NOT EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id);

SELECT s.start_date, s.monthly_fee, c.city
FROM subscriptions s
LEFT JOIN customers c ON s.customer_id = c.id;

SELECT status, amount, amount * shipping_fee AS amount_with_shipping
FROM orders
WHERE shipping_fee IS NOT NULL;

SELECT c.id, c.city, c.country
FROM customers c
WHERE EXISTS (SELECT 1 FROM accounts a WHERE a.customer_id = c.id AND a.balance BETWEEN 29000 AND 42000);

select id, brand, stock_qty
from (
    select *, row_number() over (partition by brand order by stock_qty desc, id) as row_num
    from products
) as t
where row_num <= 5;

select p.price, p.product_name, i.last_restock
from products p
left join inventory i on p.id = i.product_id;

select id, region, opened_date
from (
    select
        id,
        region,
        opened_date,
        row_number() over (partition by region order by opened_date, id) as pos
    from stores
) as t
where pos = 1;

SELECT MONTH(hire_date) hire_month, AVG(salary) avg_salary
FROM employees
GROUP BY MONTH(hire_date);

SELECT id, duration_sec
FROM web_events
WHERE duration_sec > (SELECT MAX(duration_sec) FROM web_events);

SELECT *, CASE WHEN page = '/home' THEN 1 ELSE 0 END AS is_home
FROM web_events
WHERE page = '/product';

SELECT DISTINCT status
FROM subscriptions
WHERE monthly_fee >= 90;

select id, start_date
from subscriptions
where start_date = (select max(start_date) from subscriptions);

SELECT *, SUBSTRING(page, 1, 2) page_prefix, LENGTH(page) page_length
FROM web_events
WHERE session_id IN (1, 23, 24);

SELECT id, amount
FROM payments
WHERE amount > (SELECT MAX(amount) FROM payments);

SELECT *
FROM suppliers
WHERE rating >= 2.2;

SELECT MAX(paid_at) AS latest_paid_at, SUM(CASE WHEN status = 'FAILED' THEN amount ELSE 0 END) AS failed_amount
FROM payments
ORDER BY latest_paid_at;

SELECT DATE_FORMAT(launch_date, 'yyyy-MM') AS launch_month, CASE WHEN brand IN ('Umbrella', 'Globex') THEN 'group_a' ELSE 'other' END AS brand_group, ROUND(STDDEV(stock_qty), 2) AS stddev_stock_qty
FROM products
GROUP BY 1, 2;

SELECT s.id, s.city, s.sqft
FROM stores s
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.store_id = s.id AND o.shipping_fee <= 30);

SELECT AVG(rating) AS avg_rating, MAX(rating) AS max_rating
FROM suppliers
ORDER BY max_rating ASC;

SELECT s.id, s.delivered_date, s.shipped_date
FROM shipments s
WHERE s.shipped_date BETWEEN '2023-05-01' AND '2023-08-29' AND s.order_id NOT IN (SELECT id FROM orders WHERE discount BETWEEN 0.14 AND 0.31);

SELECT *
FROM suppliers
WHERE supplier_name LIKE '%Whol%';

SELECT *, CAST(quantity AS DOUBLE) AS quantity_num, DATE_TRUNC('YEAR', last_restock) AS last_restock_period
FROM inventory
ORDER BY quantity, id;

SELECT * FROM (SELECT level, job_title, salary FROM employees)
PIVOT (MAX(salary) FOR job_title IN ('Intern', 'Designer', 'Director', 'Engineer'))
ORDER BY level;

select country, min_credit_limit, country_values
from (
    select country, min(credit_limit) as min_credit_limit, concat_ws(', ', sort_array(collect_set(country))) as country_values
    from customers
    group by country
) as t
where min_credit_limit >= 16000;

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (MAX(rating) FOR country IN ('SG', 'UK', 'TH'))
ORDER BY city;

SELECT id, rating
FROM suppliers
WHERE rating > (SELECT AVG(rating) FROM suppliers);

SELECT id, account_type, status
FROM accounts
WHERE customer_id IS NOT NULL AND account_type IN ('CREDIT', 'CHECKING', 'LOAN') AND status IN ('OPEN', 'FROZEN', 'CLOSED');

SELECT *
FROM subscriptions
WHERE monthly_fee <= 120 AND plan IN ('premium', 'enterprise');

SELECT product_id, revenue, COALESCE(units, 0) AS units_filled
FROM store_sales
WHERE revenue > 2200;

select id, store_id, date_sub(sale_date, 19) as sale_date_minus_19d
from store_sales
order by sale_date_minus_19d;

select event_time, hour(event_time) as event_time_hour
from web_events
order by event_time;

select txn_cohort, amount_range, merchant_list
from (
    select case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end as txn_cohort, max(amount) - min(amount) as amount_range, sort_array(collect_set(merchant)) as merchant_list
    from transactions
    group by case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end
) as sub
where amount_range >= 45
order by txn_cohort;

SELECT * FROM (SELECT status, method, amount FROM payments)
PIVOT (MAX(amount) FOR method IN ('bank_transfer', 'cash', 'card', 'promptpay'))
ORDER BY status;

SELECT product_id, quantity, ROUND(unit_price / quantity, 2) line_total
FROM order_items
WHERE unit_price >= 150;

SELECT country, LENGTH(name) AS name_length
FROM customers
WHERE age IS NOT NULL;

select web_events.id, web_events.duration_sec
from web_events
where web_events.session_id in (1, 12) and web_events.session_id not in (select id from sessions where browser in ('Firefox', 'Edge'));

SELECT COUNT(price) AS price_count, ROUND((100 * SUM(CASE WHEN brand = 'Umbrella' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_umbrella, COUNT(DISTINCT stock_qty) AS unique_brands
FROM products
ORDER BY pct_umbrella DESC;

SELECT order_id, status, SUBSTRING(method, 1, 3) AS method_prefix
FROM payments
WHERE NOT (order_id IS NULL AND amount < 1470 AND order_id IS NULL);

SELECT last_restock, DATE_TRUNC('WEEK', last_restock) AS last_restock_period, ADD_MONTHS(last_restock, 3) AS last_restock_plus_months
FROM inventory
WHERE store_id IN (4, 5) AND YEAR(last_restock) = 2023;

SELECT supplier_name, rating, city
FROM suppliers
WHERE LOWER(supplier_name) LIKE '%aci%' AND country IN ('TH', 'US');

SELECT DISTINCT level
FROM employees
WHERE full_name LIKE '%Grace%';

select *
from (
    select *, row_number() over (partition by country order by credit_limit, id) as pos
    from customers
) as t
where pos = 1;

select a.id, a.status
from accounts a
where a.customer_id is null and a.customer_id not in (select id from customers where email like '%@mail.co.th');

SELECT account_type, MAX(opened_date) AS latest_opened_date, MAX(opened_date) AS last_opened_date
FROM accounts
GROUP BY account_type;

SELECT account_type
FROM accounts
WHERE opened_date >= '2025-06-27';

SELECT * FROM (SELECT carrier, status, cost FROM shipments)
PIVOT (MAX(cost) FOR status IN ('IN_TRANSIT', 'LOST', 'RETURNED'))
ORDER BY carrier;

select case when cost >= 87 then 'high' when cost >= 40 then 'mid' else 'low' end as cost_bucket, max(shipped_date) as latest_shipped_date
from shipments
group by case when cost >= 87 then 'high' when cost >= 40 then 'mid' else 'low' end;

select *
from (
    select *, row_number() over (partition by customer_id order by started_at desc, id) rn
    from sessions
) ranked
where rn <= 5;

SELECT *
FROM inventory
WHERE quantity BETWEEN 77 AND 104 AND product_id IN (3, 4, 6, 8);

SELECT *, CASE WHEN is_active THEN 'Yes' ELSE 'No' END AS is_active_label
FROM customers
WHERE is_active = TRUE;

SELECT DISTINCT account_type
FROM accounts
WHERE account_type != 'LOAN';

select quarter(event_time) as event_quarter, date_format(event_time, 'yyyy-MM') as event_month, max(duration_sec) - min(duration_sec) as duration_sec_range
from web_events
group by 1, 2;

select segment, city, jp_credit_limit
from (
    select segment, city, sum(case when country = 'JP' then credit_limit else 0 end) as jp_credit_limit
    from customers
    group by segment, city
) as s
where jp_credit_limit < 74
order by city, segment
limit 5;

SELECT a.id, a.customer_id
FROM accounts a
WHERE a.customer_id NOT IN (SELECT id FROM customers WHERE city = 'London');

select id, product_id, date_format(last_restock, 'yyyy-MM-dd') as last_restock_label
from inventory
where product_id in (2, 8);

SELECT *
FROM customers
WHERE age > 58 AND segment IN ('Corporate', 'SMB', 'Consumer');

select date_format(last_restock, 'yyyy-MM') as last_restock_month, min(last_restock) as first_last_restock
from inventory
group by last_restock_month;

SELECT id, quantity
FROM inventory
WHERE quantity >= (SELECT MAX(quantity) FROM inventory WHERE last_restock < '2025-10-24');

SELECT is_active
FROM customers
WHERE segment = 'Consumer';

SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, ROUND(AVG(units), 2) AS avg_units, AVG(revenue) AS avg_revenue
FROM store_sales
GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END;

SELECT DATE_FORMAT(sale_date, 'yyyy-MM') AS sale_month, COUNT(units) AS units_count
FROM store_sales
GROUP BY DATE_FORMAT(sale_date, 'yyyy-MM');

SELECT MAX(amount) AS max_amount, COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END) AS refunded_count
FROM payments
WHERE method IN ('bank_transfer', 'paypal') AND (status <> 'REFUNDED' OR order_id = 7);

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (SUM(rating) FOR country IN ('DE', 'US', 'UK', 'SG'))
ORDER BY city;

SELECT d.id, d.dept_name, d.location
FROM departments d
WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);

select *
from (
    select *, row_number() over (partition by country order by rating desc, id) as rnk
    from suppliers
) as r
where rnk = 1
order by country;

SELECT id, last_restock, product_id
FROM inventory
WHERE last_restock = (SELECT MIN(last_restock) FROM inventory);

SELECT *, amount + shipping_fee AS amount_with_shipping
FROM orders
WHERE customer_id IS NOT NULL AND (shipping_fee BETWEEN 27 AND 36 OR shipping_fee >= 39);

SELECT customer_id
FROM orders
WHERE channel = 'web' AND amount > 1230;

select category, unique_brands
from (
    select category, count(distinct price) as unique_brands
    from products
    group by category
) as x
where unique_brands > 9
order by category, unique_brands desc;

SELECT id, store_name, TRIM(city) AS clean_city
FROM stores
WHERE store_name LIKE 'Ai%' AND region <> 'North';

SELECT CASE WHEN region IN ('East', 'South') THEN 'group_a' ELSE 'other' END AS region_group, MAX(sqft) - MIN(sqft) AS sqft_range
FROM stores
GROUP BY CASE WHEN region IN ('East', 'South') THEN 'group_a' ELSE 'other' END;

SELECT DISTINCT page
FROM web_events
WHERE page != '/home';

SELECT COUNT(quantity) AS quantity_count
FROM order_items
WHERE quantity <= 8 AND unit_price >= 250;

select *
from (
    select channel, status, sum(amount) as total_amount
    from orders
    where store_id is not null
    group by channel, status
) as sub
where total_amount < 9300
order by total_amount desc, channel;

SELECT id, shipping_fee, COALESCE(channel, 'Unknown') AS channel_filled
FROM orders
WHERE status = 'COMPLETED' AND store_id IN (30, 33, 37);

SELECT merchant, MAX(txn_time) last_txn_time, SUM(CASE WHEN txn_type = 'REFUND' THEN 1 ELSE 0 END) refund_count
FROM transactions
GROUP BY merchant;

select store_id, max(units) as max_units, count(*) as row_count
from store_sales
group by store_id;

SELECT * FROM (SELECT DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_month, method, amount FROM payments)
PIVOT (SUM(amount) FOR method IN ('promptpay', 'cash', 'card', 'paypal'))
ORDER BY paid_month;

SELECT * FROM (SELECT category, brand, cost FROM products)
PIVOT (SUM(cost) FOR brand IN ('Acme', 'Umbrella', 'Initech'))
ORDER BY category;

SELECT job_title, is_remote
FROM employees
WHERE full_name IS NOT NULL AND full_name LIKE '%Ross%' AND salary > 102000;

SELECT * FROM (SELECT txn_type, merchant, amount FROM transactions WHERE TO_DATE(txn_time) >= '2025-02-16')
PIVOT (AVG(amount) FOR merchant IN ('Grab', '7-Eleven', 'Starbucks', 'Amazon'))
ORDER BY txn_type;

SELECT * FROM (SELECT page, event_type, duration_sec FROM web_events)
PIVOT (AVG(duration_sec) FOR event_type IN ('click', 'purchase', 'search', 'page_view'))
ORDER BY page;

SELECT d.id, d.location
FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);

SELECT ROUND((100 * SUM(CASE WHEN channel = 'web' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_web, SORT_ARRAY(COLLECT_SET(status)) AS status_list
FROM orders
ORDER BY pct_web DESC;

SELECT name
FROM customers
WHERE UPPER(TRIM(name)) = 'CAROL DIAZ' AND name IS NOT NULL;

select *
from (
    select store_id, case when revenue >= 3500 then 'high' when revenue >= 800 then 'mid' else 'low' end revenue_bucket, max(units) max_units
    from store_sales
    group by store_id, case when revenue >= 3500 then 'high' when revenue >= 800 then 'mid' else 'low' end
) agg
where max_units > 17;

select merchant, refund_count
from (
    select merchant, count(case when txn_type = 'REFUND' then 1 end) as refund_count
    from transactions
    group by merchant
) as x
where refund_count > 3
order by refund_count desc, merchant
limit 10;

select dept_name, department_count
from (
    select dept_name, count(*) department_count
    from departments
    where budget <= 1720000
    group by dept_name
) sub
where department_count >= 7;

SELECT * FROM (SELECT page, event_type, duration_sec FROM web_events WHERE event_type = 'search')
PIVOT (COUNT(duration_sec) FOR event_type IN ('click', 'page_view', 'search', 'add_to_cart'))
ORDER BY page;

select i.store_id, p.price, p.stock_qty
from inventory i
inner join products p on i.product_id = p.id;

SELECT browser, device, CASE WHEN device = 'desktop' THEN 1 ELSE 0 END AS is_desktop
FROM sessions
WHERE customer_id IN (7, 20) AND customer_id IS NULL;

SELECT order_id, CASE WHEN unit_price >= 380 THEN 'High' WHEN unit_price >= 110 THEN 'Medium' ELSE 'Low' END AS unit_price_level
FROM order_items
WHERE product_id IS NULL AND order_id IN (6, 31, 32, 38);

SELECT * FROM (SELECT event_type, page, duration_sec FROM web_events)
PIVOT (AVG(duration_sec) FOR page IN ('/product', '/checkout', '/home'))
ORDER BY event_type;

SELECT id, country, DATEDIFF(CURRENT_DATE(), started_at) AS days_since_started_at
FROM sessions
WHERE customer_id = 16 AND (customer_id = 15 OR browser IS NOT NULL);

SELECT * FROM (SELECT MONTH(hire_date) AS hire_month, level, salary FROM employees)
PIVOT (MAX(salary) FOR level IN ('L2', 'L5', 'L3', 'L1'))
ORDER BY hire_month;

SELECT s.id, s.sqft, s.store_name
FROM stores s
WHERE s.region IN ('West', 'East') AND s.id IN (SELECT store_id FROM inventory WHERE product_id IN (5, 8));

SELECT id, amount
FROM payments
WHERE amount <= (SELECT MIN(amount) FROM payments);

SELECT MAX(budget) - MIN(budget) AS budget_range, AVG(budget) AS avg_budget
FROM departments
WHERE dept_name <> 'Legal';

select country, min(rating) as min_rating
from suppliers
group by country;

SELECT * FROM (SELECT region, city, sqft FROM stores)
PIVOT (COUNT(sqft) FOR city IN ('London', 'Chiang Mai'))
ORDER BY region;

SELECT CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) job_title_values, MIN(salary) min_salary, ROUND(AVG(salary), 2) avg_salary
FROM employees
WHERE manager_id IS NOT NULL;

select s.id, s.opened_date
from stores s
where s.sqft >= 6148 and exists (select 1 from store_sales ss where ss.store_id = s.id);

SELECT supplier_name
FROM suppliers
WHERE country = 'SG' AND supplier_name NOT LIKE 'Si%' AND country = 'SG';

SELECT city, COUNT(CASE WHEN city = 'London' THEN 1 END) london_count
FROM stores
GROUP BY city;

SELECT s.id, s.opened_date, s.store_name
FROM stores s
WHERE s.id IN (SELECT store_id FROM store_sales);

SELECT a.id, a.status
FROM accounts a
WHERE a.customer_id NOT IN (SELECT id FROM customers WHERE age IS NOT NULL);

SELECT o.id, o.order_date
FROM orders o
WHERE o.customer_id IN (SELECT id FROM customers WHERE LENGTH(name) > 7);

SELECT COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT(DISTINCT budget) AS unique_locations, SUM(CASE WHEN location = 'Bangkok' THEN budget ELSE 0 END) AS bangkok_budget
FROM departments
ORDER BY bangkok_budget DESC, unique_locations DESC;

select end_month, unique_statuss, premium_count
from (
    select month(end_date) end_month, count(distinct monthly_fee) unique_statuss, count(case when plan = 'premium' then 1 end) premium_count
    from subscriptions
    where start_date >= '2025-05-11'
    group by month(end_date)
) s
where premium_count >= 6
order by premium_count desc;

SELECT s.id, s.store_name
FROM stores s
WHERE NOT EXISTS (SELECT 1 FROM store_sales ss WHERE ss.store_id = s.id AND ss.units IS NOT NULL);

SELECT txn_type, is_flagged, merchant
FROM transactions
ORDER BY merchant;

select id, sqft
from stores
where sqft <= (select min(sqft) from stores where city <> 'Tokyo');

SELECT event_type, SUM(duration_sec) total_duration_sec, ROUND(SUM(duration_sec) * 100.0 / SUM(SUM(duration_sec)) OVER (), 2) AS pct_of_total
FROM web_events
GROUP BY event_type;

SELECT order_id, SUM(cost) total_cost, SUM(SUM(cost)) OVER (ORDER BY order_id) AS cumulative_cost
FROM shipments
GROUP BY order_id;

select *
from (
    select order_id, count(distinct quantity) unique_products
    from order_items
    group by order_id
) x
where unique_products > 7
order by order_id
limit 3;

select id, product_id, unit_price - quantity as line_total
from order_items
where product_id in (12, 23);

SELECT id, amount
FROM transactions
WHERE amount > (SELECT AVG(amount) FROM transactions);

SELECT id, opened_date, account_type
FROM accounts
WHERE opened_date > (SELECT MAX(opened_date) FROM accounts WHERE customer_id IS NULL);

SELECT * FROM (SELECT DATE_FORMAT(start_date, 'yyyy-MM') AS start_month, plan, monthly_fee FROM subscriptions WHERE status NOT IN ('PAUSED', 'CANCELLED'))
PIVOT (AVG(monthly_fee) FOR plan IN ('basic', 'enterprise'))
ORDER BY start_month;

SELECT id, stock_qty, CONCAT(category, ', ', product_name) AS category_product_name
FROM products
WHERE price > 520;

select suppliers.id, suppliers.rating, suppliers.country
from suppliers
where suppliers.id in (select supplier_id from products where product_name is not null);

SELECT departments.id, departments.dept_name, departments.budget
FROM departments
WHERE departments.location <> 'Tokyo' AND EXISTS (SELECT 1 FROM employees WHERE employees.dept_id = departments.id);

SELECT o.id, o.channel
FROM orders o
WHERE o.customer_id IS NOT NULL AND o.store_id NOT IN (SELECT id FROM stores WHERE sqft <> 8917);

SELECT sale_date, revenue, DATE_TRUNC('MONTH', sale_date) AS sale_date_period
FROM store_sales
WHERE revenue IS NOT NULL;

select orders.id, orders.store_id, orders.discount
from orders
where exists (select 1 from order_items where order_items.order_id = orders.id and order_items.quantity = 6);

SELECT subscriptions.id, subscriptions.customer_id, subscriptions.monthly_fee
FROM subscriptions
WHERE subscriptions.monthly_fee >= 220 AND subscriptions.customer_id IN (SELECT id FROM customers WHERE credit_limit > 8000);

SELECT s.id, s.started_at
FROM sessions s
WHERE NOT EXISTS (SELECT 1 FROM web_events we WHERE we.session_id = s.id AND we.event_time < '2025-08-28');

SELECT o.id, o.discount
FROM orders o
WHERE EXISTS (SELECT 1 FROM shipments s WHERE s.order_id = o.id);

SELECT id, amount, RANK() OVER (ORDER BY amount) AS amount_rank
FROM payments
WHERE amount < 1590;

SELECT *
FROM order_items
WHERE quantity BETWEEN 5 AND 7;

SELECT we.id, we.event_time, we.session_id
FROM web_events we
WHERE we.session_id IN (SELECT id FROM sessions WHERE customer_id = 25);

select s.id, s.started_at, s.customer_id
from sessions s
where s.device in ('tablet', 'mobile') and not exists (select 1 from web_events we where we.session_id = s.id and we.page = '/product');

SELECT revenue, product_id
FROM store_sales
WHERE store_id IN (2, 3, 4, 6);

SELECT customer_id, DATE_TRUNC('month', opened_date) AS opened_date_period
FROM accounts
WHERE MONTH(opened_date) IN (1, 7, 12);

SELECT merchant, MAX(amount) - MIN(amount) AS amount_range
FROM transactions
GROUP BY merchant;

select s.id, s.started_at
from sessions s
where not exists (select 1 from web_events we where we.session_id = s.id);

SELECT budget, dept_name
FROM departments
WHERE dept_name IN ('Legal', 'HR', 'Sales');

select * from (select order_id, status, cost from shipments)
pivot (sum(cost) for status in ('IN_TRANSIT', 'RETURNED', 'DELIVERED', 'LOST'))
order by order_id;

select status, sum(cost) as total_cost, dense_rank() over (order by sum(cost) desc) as rnk
from shipments
group by status;

select opened_month, balance_range
from (
    select date_trunc('MONTH', opened_date) as opened_month, max(balance) - min(balance) as balance_range
    from accounts
    group by date_trunc('MONTH', opened_date)
) as t
where balance_range < 53
order by balance_range, opened_month
limit 5;

SELECT p.id, p.order_id, p.amount
FROM payments p
WHERE p.method IN ('bank_transfer', 'promptpay', 'card') AND p.order_id IN (SELECT id FROM orders WHERE status = 'COMPLETED');

select *
from (
    select *, row_number() over (partition by region order by opened_date desc, id) as rn
    from stores
    where store_name like '%Mall%'
) as r
where rn <= 2;

select order_id, round(stddev(quantity), 2) as stddev_quantity, count(*) as row_count
from order_items
group by order_id;

select location, dept_name
from departments
where budget < 1342000 and budget < 3747000;

SELECT id, revenue, CAST(units AS STRING) AS units_str
FROM store_sales
WHERE product_id = 10 AND revenue <= 3800;

SELECT opened_date, region, store_name
FROM stores
WHERE store_name IS NULL;

SELECT city, SORT_ARRAY(COLLECT_SET(city)) AS city_list
FROM stores
GROUP BY city;

SELECT id, rating, supplier_name
FROM suppliers
WHERE rating > (SELECT MAX(rating) FROM suppliers WHERE country = 'US');

SELECT s.cost, o.store_id, CASE WHEN s.status = 'LOST' THEN 1 ELSE 0 END AS is_lost
FROM shipments s
INNER JOIN orders o ON o.id = s.order_id;

SELECT email, dept_id, hire_date
FROM employees
WHERE salary > 135000 AND manager_id IS NOT NULL;

select *
from (
    select region, min(opened_date) as min_opened_date, count(sqft) as sqft_count
    from stores
    group by region
) as sub
where sqft_count < 5
order by sqft_count;

select id, credit_limit, signup_date
from customers
where credit_limit < (select min(credit_limit) from customers);

SELECT is_remote, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values, MAX(salary) - MIN(salary) AS salary_range
FROM employees
GROUP BY 1;

SELECT s.id, s.city
FROM stores s
WHERE s.id IN (SELECT store_id FROM inventory WHERE last_restock < '2025-05-01');

SELECT *
FROM (
    SELECT *, RANK() OVER (PARTITION BY brand ORDER BY launch_date DESC) AS pos
    FROM products
) AS ranked
WHERE pos <= 3;

select city, sum(sqft) as total_sqft, round(sum(sqft) * 100.0 / sum(sum(sqft)) over (), 2) as pct_of_total
from stores
group by city;

SELECT id, balance, customer_id
FROM accounts
WHERE balance >= (SELECT MAX(balance) FROM accounts);

SELECT *, UPPER(country) AS country_upper, CASE WHEN credit_limit >= 18000 THEN 'High' WHEN credit_limit >= 6500 THEN 'Medium' ELSE 'Low' END AS credit_limit_tier
FROM customers
WHERE email IS NOT NULL AND credit_limit <= 4900;

SELECT order_id, product_id, MAX(quantity) - MIN(quantity) AS quantity_range
FROM order_items
GROUP BY order_id, product_id;

