FROM stores s
WHERE s.region IN ('East', 'South') AND NOT EXISTS (SELECT 1 FROM inventory i WHERE i.store_id = s.id);

SELECT MONTH(order_date) AS order_month, MAX(shipping_fee) - MIN(shipping_fee) AS shipping_fee_range
FROM orders
GROUP BY order_month;

SELECT id, customer_id, discount
FROM (
    SELECT *, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY discount) AS pos
    FROM orders
) AS ranked
WHERE pos = 1;

SELECT id, end_date, monthly_fee
FROM subscriptions
WHERE end_date > (SELECT MAX(end_date) FROM subscriptions);

select product_id, quantity, round(quantity, 0) as quantity_rounded
from inventory
where not (last_restock > '2024-01-01' and product_id = 5);

select *
from (
    select plan, avg(monthly_fee) avg_monthly_fee
    from subscriptions
    where plan != 'standard'
    group by plan
) s
where avg_monthly_fee >= 180
order by avg_monthly_fee;

SELECT SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list, COUNT(CASE WHEN job_title = 'Manager' THEN 1 END) AS manager_count
FROM employees
WHERE is_remote = TRUE;

select distinct merchant, txn_type
from transactions
where is_flagged = true;

SELECT id, unit_price, product_id
FROM order_items
WHERE unit_price >= (SELECT AVG(unit_price) FROM order_items WHERE product_id IS NOT NULL);

SELECT *
FROM suppliers
WHERE rating BETWEEN 2.0 AND 3.1;

SELECT MIN(revenue) AS min_revenue
FROM store_sales
WHERE store_id IN (3, 4, 6);

SELECT s.id, s.device, s.started_at
FROM sessions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE name LIKE 'J%');

SELECT d.id, d.location, d.dept_name
FROM departments d
WHERE d.location IN ('New York', 'Tokyo') AND EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND YEAR(e.hire_date) >= 2024);

SELECT * FROM (SELECT event_type, page, duration_sec FROM web_events)
PIVOT (MAX(duration_sec) FOR page IN ('/search', '/home', '/checkout'))
ORDER BY event_type;

SELECT p.id, p.status, p.amount
FROM payments p
WHERE p.order_id IN (SELECT id FROM orders WHERE status = 'CANCELLED');

select status, total_discount, stddev_shipping_fee
from (
    select status, sum(discount) as total_discount, round(stddev(shipping_fee), 2) as stddev_shipping_fee
    from orders
    group by status
) as x
where total_discount >= 1.2
order by stddev_shipping_fee;

select hire_month, num_employees
from (
    select date_format(hire_date, 'yyyy-MM') as hire_month, count(*) as num_employees
    from employees
    where level != 'L3'
    group by date_format(hire_date, 'yyyy-MM')
) as x
where num_employees < 10
order by num_employees desc;

SELECT id, category, SORT_ARRAY(tags) AS sorted_tags
FROM products
ORDER BY id;

select *
from (
    select store_id, max(units) as max_units
    from store_sales
    group by store_id
) as sub
where max_units > 32
order by 2 desc, store_id
limit 20;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY opened_date DESC, id) rnk
    FROM accounts
) r
WHERE rnk <= 2;

SELECT * FROM (SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, job_title, salary FROM employees)
PIVOT (AVG(salary) FOR job_title IN ('Analyst', 'Manager', 'Director', 'Engineer'))
ORDER BY hire_cohort;

SELECT status, customer_id
FROM accounts
WHERE customer_id IN (6, 21, 32) AND opened_date >= '2024-03-01';

SELECT *, CASE WHEN txn_type IN ('FEE', 'CREDIT') THEN 'Group A' ELSE 'Other' END AS txn_type_group
FROM transactions
WHERE is_flagged;

SELECT id, event_time
FROM web_events
WHERE event_time < '2023-06-18' AND duration_sec = 183;

SELECT SUM(CASE WHEN country = 'US' THEN age ELSE 0 END) AS us_age
FROM customers
ORDER BY us_age DESC;

SELECT id, store_name
FROM stores
ORDER BY id DESC, store_name;

