sql:
SELECT *
FROM inventory
WHERE quantity <> 236;

SELECT * FROM (SELECT city, region, sqft FROM stores WHERE UPPER(TRIM(store_name)) = 'OLD TOWN')
PIVOT (MAX(sqft) FOR region IN ('South', 'East'))
ORDER BY city;

SELECT *, INITCAP(TRIM(method)) AS method_title
FROM payments
WHERE order_id IS NOT NULL;

SELECT DISTINCT browser, country
FROM sessions
WHERE country != 'DE';

select id, is_flagged, substring(merchant, 1, 2) as merchant_prefix
from transactions
where not is_flagged and account_id in (23, 25, 28);

SELECT COUNT(age) AS age_count, COUNT(*) AS total_count
FROM customers
WHERE is_active;

SELECT id, event_time, CASE WHEN duration_sec >= 371 THEN 'High' WHEN duration_sec >= 93 THEN 'Medium' ELSE 'Low' END AS duration_sec_band
FROM web_events
ORDER BY duration_sec_band;

SELECT DISTINCT category, brand
FROM products
WHERE supplier_id IS NOT NULL;

SELECT id, email, credit_limit
FROM customers
WHERE name LIKE 'No%' OR credit_limit > 7100;

SELECT store_id, COALESCE(revenue, 0) revenue_filled, WEEKOFYEAR(sale_date) sale_date_weekofyear
FROM store_sales
WHERE revenue > 3400;

select *
from customers
where age != 60 and (segment = 'SMB' or credit_limit < 15000);

SELECT id, city
FROM customers
ORDER BY 2, 1 DESC;

SELECT *, CEIL(quantity) AS quantity_whole
FROM inventory
WHERE product_id IN (2, 4, 9) AND last_restock > '2024-03-01';

select id, rating, lag(rating, 1) over (order by rating, id) as prev_rating
from suppliers
where country in ('DE', 'US');

SELECT p.id, p.launch_date, p.product_name
FROM products p
WHERE p.category = 'Books' AND EXISTS (SELECT 1 FROM inventory i WHERE i.product_id = p.id AND i.last_restock BETWEEN '2023-07-01' AND '2024-04-11');

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) AS pos
    FROM sessions
) AS t
WHERE pos = 1;

select event_time, duration_sec
from web_events
order by duration_sec desc;

select id, account_id
from transactions
where not (amount < 3500 and account_id in (1, 3, 7, 21) and hour(txn_time) between 6 and 14);

select year(signup_date) as signup_year, count(distinct age) as unique_segments, sum(case when segment = 'Corporate' then credit_limit else 0 end) as corporate_credit_limit
from customers
group by year(signup_date);

select * from (select status, carrier, cost from shipments)
pivot (max(cost) for carrier in ('FedEx', 'DHL'))
order by status;

SELECT rating, CAST(rating AS INT) AS rating_int, COALESCE(city, 'Unknown') AS city_filled
FROM suppliers
WHERE city = 'Singapore' AND city = 'London';

SELECT id, status, balance
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY balance DESC, id) AS pos
    FROM accounts
) AS r
WHERE pos <= 3;

SELECT txn_type, MIN(amount) AS min_amount
FROM transactions
GROUP BY txn_type;

select a.id, a.customer_id
from accounts a
where a.customer_id in (select id from customers where country not in ('TH', 'DE'));

select *
from (
    select *, row_number() over (partition by city order by rating desc, id) as rn
    from suppliers
) as t
where rn <= 2
order by rn desc;

SELECT YEAR(start_date) AS start_year, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee, COUNT(monthly_fee) AS monthly_fee_count
FROM subscriptions
GROUP BY start_year;

SELECT id, product_id, COUNT(*) OVER (PARTITION BY product_id) AS product_id_count
FROM store_sales
WHERE revenue > 3600;

select customer_id, add_months(end_date, 1) as end_date_plus_months, datediff(current_date(), start_date) as days_since_start_date
from subscriptions
where end_date between '2023-07-18' and '2024-07-01' or monthly_fee is not null;

SELECT s.id, s.carrier
FROM shipments s
WHERE s.delivered_date BETWEEN '2023-07-13' AND '2025-06-02' AND s.order_id NOT IN (SELECT id FROM orders WHERE order_date < '2023-04-01');

SELECT a.id, a.balance
FROM accounts a
WHERE a.opened_date < '2023-03-01' AND a.customer_id NOT IN (SELECT id FROM customers WHERE credit_limit >= 11900);

select credit_limit_bucket, avg_age
from (
    select case when credit_limit >= 14700 then 'high' when credit_limit >= 5100 then 'mid' else 'low' end as credit_limit_bucket, round(avg(age), 2) as avg_age
    from customers
    group by case when credit_limit >= 14700 then 'high' when credit_limit >= 5100 then 'mid' else 'low' end
) as agg
where avg_age >= 69;

select *
from (
    select customer_id, avg(balance) as avg_balance, count(distinct balance) as unique_account_types
    from accounts
    group by customer_id
) as agg
where avg_balance >= 54000
order by unique_account_types desc, customer_id
limit 5;

SELECT id, order_id, delivered_date
FROM shipments
WHERE order_id IS NULL;

SELECT s.id, s.shipped_date
FROM shipments s
WHERE MONTH(s.delivered_date) IN (3, 9, 12) AND s.order_id NOT IN (SELECT id FROM orders WHERE order_date <= '2024-12-03');

SELECT CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(rating) AS rating_count
FROM suppliers
GROUP BY 1;

SELECT a.id, a.customer_id
FROM accounts a
WHERE a.opened_date > '2025-03-08' AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.merchant != 'Shell');

SELECT * FROM (SELECT job_title, level, salary FROM employees)
PIVOT (COUNT(salary) FOR level IN ('L3', 'L4', 'L2'))
ORDER BY job_title;

SELECT account_type, MONTH(opened_date) AS opened_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values
FROM accounts
GROUP BY account_type, MONTH(opened_date);

select *, round(salary, 2) salary_rounded
from employees
where manager_id = 3 or month(hire_date) in (2, 9, 11);

SELECT customers.id, customers.email
FROM customers
WHERE NOT customers.is_active AND customers.id IN (SELECT customer_id FROM subscriptions);

SELECT id, city, SUBSTRING(country, 1, 3) AS country_prefix
FROM suppliers
WHERE rating BETWEEN 2.2 AND 3.1;

SELECT id, budget, PERCENT_RANK() OVER (ORDER BY budget) AS budget_pct_rank
FROM departments
ORDER BY 1;

SELECT p.id, p.product_name
FROM products p
WHERE p.supplier_id IN (SELECT id FROM suppliers WHERE supplier_name IS NOT NULL);

SELECT s.id, s.store_name
FROM stores s
WHERE s.store_name LIKE '%Old%' AND s.id IN (SELECT store_id FROM store_sales);

SELECT session_id, page, TO_DATE(event_time) AS event_time_date
FROM web_events
WHERE session_id IN (12, 27);

SELECT t.id, t.is_flagged, t.txn_time
FROM transactions t
WHERE t.account_id IN (SELECT id FROM accounts WHERE balance >= 21000);

SELECT i.id, i.last_restock, i.store_id
FROM inventory i
WHERE i.store_id IN (1, 3) AND i.product_id IN (SELECT id FROM products WHERE cost < 300);

SELECT device, browser
FROM sessions
WHERE country = 'TH' AND customer_id IS NOT NULL;

SELECT a.id, a.balance, a.opened_date
FROM accounts a
WHERE a.account_type IN ('CHECKING', 'LOAN', 'CREDIT') AND EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.account_id IN (28, 32, 38, 40));

SELECT id, store_id, COALESCE(discount, 0) AS discount_filled
FROM orders
WHERE order_date <= '2025-05-01' AND (shipping_fee BETWEEN 29 AND 31 OR shipping_fee >= 25);

SELECT sessions.country, customers.city, customers.is_active
FROM sessions
LEFT OUTER JOIN customers ON sessions.customer_id = customers.id;

SELECT id, location, LOWER(location) AS location_lower
FROM departments
ORDER BY id DESC;

SELECT CASE WHEN duration_sec >= 515 THEN 'high' WHEN duration_sec >= 180 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, event_type, ROUND(AVG(duration_sec), 2) AS avg_duration_sec
FROM web_events
GROUP BY 1, 2;

SELECT c.id, c.is_active
FROM customers c
WHERE c.segment NOT IN ('Consumer', 'SMB', 'Corporate') AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id = c.id AND s.monthly_fee <= 80);

select is_remote, salary_bucket, l1_count
from (
    select is_remote, case when salary >= 146000 then 'high' when salary >= 64000 then 'mid' else 'low' end as salary_bucket, count(case when level = 'L1' then 1 end) as l1_count
    from employees
    where dept_id in (1, 22, 33)
    group by is_remote, case when salary >= 146000 then 'high' when salary >= 64000 then 'mid' else 'low' end
) as agg
where l1_count > 8
order by salary_bucket, 3, is_remote
limit 5;

SELECT MIN(amount) min_amount
FROM payments
WHERE paid_at < '2025-05-01' AND HOUR(paid_at) BETWEEN 10 AND 13 AND order_id = 12;

SELECT hire_date, is_remote, full_name
FROM employees
ORDER BY full_name DESC;

SELECT account_id, CAST(is_flagged AS INT) AS is_flagged_flag
FROM transactions
ORDER BY is_flagged_flag DESC;

SELECT txn_type, amount, CONCAT(txn_type, ' ', merchant) AS txn_type_merchant
FROM transactions
WHERE amount IS NOT NULL OR TO_DATE(txn_time) >= '2024-10-01';

SELECT id, hire_date, salary
FROM employees
WHERE hire_date = (SELECT MIN(hire_date) FROM employees);

SELECT *
FROM shipments
WHERE YEAR(delivered_date) = 2024;

SELECT ROUND(AVG(amount), 2) AS avg_amount, SUM(CASE WHEN method = 'bank_transfer' THEN amount ELSE 0 END) AS bank_transfer_amount
FROM payments
ORDER BY bank_transfer_amount;

select *
from (
    select case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end last_restock_cohort, count(*) total_count
    from inventory
    group by case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end
) sub
where total_count >= 5;

select *, length(dept_name) dept_name_length
from departments
where location is not null or dept_name = 'Engineering';

SELECT id, started_at, RANK() OVER (ORDER BY started_at DESC) AS started_at_rank
FROM sessions
ORDER BY started_at;

select c.id, c.signup_date
from customers c
where not exists (select 1 from orders o where o.customer_id = c.id and o.discount >= 0.11);

SELECT id, discount, customer_id
FROM orders
WHERE status <> 'RETURNED';

select d.id, d.dept_name
from departments d
where d.dept_name in ('HR', 'Engineering') and not exists (select 1 from employees e where e.dept_id = d.id and lower(trim(e.email)) = 'grace.kim@gmail.com');

SELECT d.id, d.location, d.budget
FROM departments d
WHERE d.id IN (SELECT dept_id FROM employees WHERE full_name NOT LIKE '%Che%');

SELECT a.opened_date, t.merchant, t.amount
FROM accounts a
INNER JOIN transactions t ON a.id = t.account_id;

select order_id, min_quantity
from (
    select order_id, min(quantity) as min_quantity
    from order_items
    group by order_id
) as agg
where min_quantity >= 4.4;

select round((100 * sum(case when country = 'DE' then 1 else 0 end)) / count(*), 1) as pct_de
from customers
where email like '%@startup.io' and (is_active or segment != 'Corporate');

SELECT *, WEEKOFYEAR(last_restock) last_restock_weekofyear
FROM inventory
WHERE quantity >= 162;

SELECT *, DAYOFWEEK(order_date) AS order_date_dayofweek
FROM orders
WHERE customer_id IS NULL;

select store_id, last_restock_month, avg_quantity
from (
    select store_id, date_format(last_restock, 'yyyy-MM') as last_restock_month, avg(quantity) as avg_quantity
    from inventory
    group by store_id, date_format(last_restock, 'yyyy-MM')
) as sub
where avg_quantity >= 160;

select p.id, p.launch_date
from products p
where p.supplier_id in (select id from suppliers where country = 'DE');

select a.id, a.customer_id
from accounts a
where not exists (select 1 from transactions t where t.account_id = a.id);

SELECT *, UPPER(store_name) store_name_upper, COALESCE(sqft, 0) sqft_filled
FROM stores
WHERE region = 'North' AND (region NOT IN ('West', 'North') OR MONTH(opened_date) IN (1, 2, 5));

SELECT id, account_id, COALESCE(merchant, 'N/A') AS merchant_filled
FROM transactions
WHERE account_id = 19 AND amount >= 4000 AND account_id IN (5, 6, 11, 20);

SELECT store_id, product_id, SUM(units) AS total_units, AVG(revenue) AS avg_revenue
FROM store_sales
GROUP BY store_id, product_id;

SELECT i.store_id, i.product_id, i.quantity, s.units
FROM inventory i
JOIN store_sales s ON i.store_id = s.store_id AND i.product_id = s.product_id;

SELECT account_id, txn_time, amount,
       SUM(amount) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS running_total
FROM transactions;

SELECT id, sale_date, revenue,
       AVG(revenue) OVER (ORDER BY sale_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7
FROM store_sales;

WITH ranked AS (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, id) AS rn
    FROM employees
)
SELECT * FROM ranked WHERE rn = 1;

SELECT * FROM (
    SELECT segment, country, credit_limit FROM customers
) PIVOT (
    SUM(credit_limit) FOR country IN ('TH', 'US', 'SG')
);
